<?php
session_start(); require_once '../conexion.php';
if (!isset($_SESSION['usuario_id']) || $_SESSION['rol'] !== 'admin') { header('Location: ../login.php'); exit; }
$id=isset($_GET['id'])?(int)$_GET['id']:0;
$stmt=$conexion->prepare("SELECT id,nombre,usuario,estado FROM usuarios WHERE id=? AND rol='operario'");$stmt->bind_param('i',$id);$stmt->execute();$resultado=$stmt->get_result();if($resultado->num_rows!==1){$stmt->close();header('Location: operarios.php?error='.urlencode('Operario no encontrado.'));exit;}$operario=$resultado->fetch_assoc();$stmt->close();
$stmt=$conexion->prepare("SELECT COUNT(*) AS total FROM pedidos WHERE operario_id=? AND estado='Completado'");$stmt->bind_param('i',$id);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$pedidos=(int)$r['total'];$stmt->close();
$stmt=$conexion->prepare("SELECT fecha,hora_inicio,hora_fin,TIMEDIFF(hora_fin,hora_inicio) AS tiempo FROM jornadas WHERE operario_id=? ORDER BY fecha DESC LIMIT 20");$stmt->bind_param('i',$id);$stmt->execute();$historial=$stmt->get_result();
$totalSeg=0;$cantidad=0;$filas=array();while($fila=$historial->fetch_assoc()){$filas[]=$fila;if($fila['hora_fin']!==null){$partes=explode(':',$fila['tiempo']);if(count($partes)>=3){$totalSeg+=(int)$partes[0]*3600+(int)$partes[1]*60+(int)$partes[2];}$cantidad++;}}$stmt->close();$horas=floor($totalSeg/3600);$minutos=floor(($totalSeg%3600)/60);$tiempo=$horas.'h '.str_pad($minutos,2,'0',STR_PAD_LEFT).'m';$promedio=$pedidos>0?round(($totalSeg/$pedidos)/60):0;$promedioTexto=$promedio.'m';
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Perfil del operario | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><nav class="sistema-navbar"><div class="navbar-brand-sistema"><div class="navbar-logo"><i class="bi bi-box-seam"></i></div><div><strong>SOFTYLE</strong><small>Panel administrativo</small></div></div><a href="operarios.php" class="btn-logout"><i class="bi bi-arrow-left"></i></a></nav><main class="admin-container"><a href="operarios.php" class="volver-link"><i class="bi bi-arrow-left"></i> Volver a operarios</a><section class="perfil-operario"><div class="perfil-icon"><i class="bi bi-person"></i></div><div class="perfil-info"><span class="dashboard-label">PERFIL DEL OPERARIO</span><h1><?php echo htmlspecialchars($operario['nombre'],ENT_QUOTES,'UTF-8');?></h1><p>Usuario: <strong><?php echo htmlspecialchars($operario['usuario'],ENT_QUOTES,'UTF-8');?></strong></p><?php if((int)$operario['estado']===1){?><span class="estado activo">Activo</span><?php }else{?><span class="estado">Inactivo</span><?php }?></div></section><section class="perfil-stats"><div class="perfil-stat"><i class="bi bi-clipboard-check"></i><span>Pedidos completados</span><strong><?php echo $pedidos;?></strong></div><div class="perfil-stat"><i class="bi bi-clock"></i><span>Tiempo trabajado</span><strong><?php echo htmlspecialchars($tiempo,ENT_QUOTES,'UTF-8');?></strong></div><div class="perfil-stat"><i class="bi bi-stopwatch"></i><span>Promedio por pedido</span><strong><?php echo htmlspecialchars($promedioTexto,ENT_QUOTES,'UTF-8');?></strong></div></section><section class="admin-table-card"><div class="section-title"><h2>Historial de trabajo</h2><p>Registro de jornadas del operario.</p></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Inicio</th><th>Fin</th><th>Tiempo</th></tr></thead><tbody><?php if(count($filas)===0){?><tr><td colspan="4" class="text-center">No hay jornadas registradas.</td></tr><?php } ?><?php foreach($filas as $fila){?><tr><td><?php echo htmlspecialchars($fila['fecha'],ENT_QUOTES,'UTF-8');?></td><td><?php echo htmlspecialchars($fila['hora_inicio'],ENT_QUOTES,'UTF-8');?></td><td><?php echo $fila['hora_fin']!==null?htmlspecialchars($fila['hora_fin'],ENT_QUOTES,'UTF-8'):'En curso';?></td><td><?php echo $fila['tiempo']!==null?htmlspecialchars($fila['tiempo'],ENT_QUOTES,'UTF-8'):'-';?></td></tr><?php }?></tbody></table></div></section></main></body></html>
